    match v {
        Bar::Foo => 8,
        Bar::Bar => 9,
        Bar::Baz => 3,
    }
}

#[no_mangle]
pub fn compare(v: Bar) -> i32 {
    match v {
        Bar::Foo => 8,
        Bar::Bar => 9,
        _ => 3,
    }
}

#[no_mangle]
pub fn lookup2(v: Bar) -> i32 {
    match v {
        Bar::Foo => 1,
        Bar::Bar => 2,
        Bar::Baz => 3,
    }
}

#[no_mangle]
pub fn compare2(v: Bar) -> i32 {
    match v {
        Bar::Foo => 1,
        Bar::Bar => 2,
        _ => 3,
    }
}
